/* ============================================================
   GRAMMAR QUESTIONS
   ============================================================ */
add("perfekt",
 "Perfekt = *haben* oder *sein* (Präsens) + *Partizip II* am Satzende. *sein* bei Bewegung (gehen, fahren, kommen) und Zustandswechsel (aufstehen, einschlafen) sowie sein/bleiben/passieren – sonst *haben*. Partizip II: ge-…-t (gemacht), stark ge-…-en (gegangen); kein ge- bei -ieren (studiert) und untrennbaren Vorsilben be-, ver-, er- (besucht).",
[
 {lvl:"e", type:"mc", q:"Ich ___ gestern ins Kino gegangen.", options:["bin","habe","war","hat"], answer:"bin", explain:"*gehen* = Bewegung → Perfekt mit *sein*."},
 {lvl:"e", type:"mc", q:"Wir ___ einen Film gesehen.", options:["haben","sind","waren","seid"], answer:"haben", explain:"*sehen* → Perfekt mit *haben* (die meisten Verben)."},
 {lvl:"e", type:"mc", q:"Was ___ du gemacht?", options:["hast","bist","warst","hattest"], answer:"hast", explain:"*machen* → Perfekt mit *haben*."},
 {lvl:"e", type:"mc", q:"Ich ___ einen Kaffee getrunken.", options:["habe","bin","war","hat"], answer:"habe", explain:"*trinken* → *haben*: 'Ich habe … getrunken.'"},
 {lvl:"e", type:"fill", q:"Partizip II von *machen*?", accept:["gemacht"], explain:"Regelmäßig: ge-…-t → *gemacht*."},
 {lvl:"e", type:"fill", q:"Partizip II von *kaufen*?", accept:["gekauft"], explain:"Regelmäßig: ge-…-t → *gekauft*."},
 {lvl:"e", type:"fill", q:"Partizip II von *spielen*?", accept:["gespielt"], explain:"Regelmäßig → *gespielt*."},
 {lvl:"e", type:"fill", q:"Partizip II von *lernen*?", accept:["gelernt"], explain:"Regelmäßig → *gelernt*."},
 {lvl:"e", type:"mc", q:"Sie ___ um 7 Uhr aufgestanden.", options:["ist","hat","war","haben"], answer:"ist", explain:"*aufstehen* = Zustandswechsel → *sein*."},
 {lvl:"m", type:"fill", q:"Partizip II von *sprechen*?", accept:["gesprochen"], explain:"Stark, Vokalwechsel → *gesprochen* (ge-…-en)."},
 {lvl:"m", type:"fill", q:"Partizip II von *studieren*?", accept:["studiert"], explain:"Verben auf *-ieren* → kein ge-: *studiert*."},
 {lvl:"m", type:"fill", q:"Partizip II von *besuchen*?", accept:["besucht"], explain:"Untrennbare Vorsilbe *be-* → kein ge-: *besucht*."},
 {lvl:"m", type:"fill", q:"Partizip II von *einkaufen*?", accept:["eingekauft"], explain:"Trennbar: ge- in der Mitte → *eingekauft*."},
 {lvl:"m", type:"fill", q:"Partizip II von *lesen*?", accept:["gelesen"], explain:"Stark → *gelesen*."},
 {lvl:"m", type:"mc", q:"Das Baby ___ sofort eingeschlafen.", options:["ist","hat","war","wurde"], answer:"ist", explain:"*einschlafen* = Zustandswechsel → *sein*."},
 {lvl:"m", type:"transform", q:"Setze ins Perfekt: „Ich esse einen Apfel.“", accept:["Ich habe einen Apfel gegessen","habe einen Apfel gegessen"], explain:"essen → gegessen, mit *haben*."},
 {lvl:"m", type:"transform", q:"Setze ins Perfekt: „Er fährt nach Berlin.“", accept:["Er ist nach Berlin gefahren","ist nach Berlin gefahren"], explain:"fahren = Bewegung → *sein*."},
 {lvl:"m", type:"mc", q:"Der Unfall ___ gestern passiert.", options:["ist","hat","war","wurde"], answer:"ist", explain:"*passieren* bildet das Perfekt immer mit *sein*."},
 {lvl:"m", type:"fill", q:"Partizip II von *bekommen*?", accept:["bekommen"], explain:"Untrennbar *be-* + stark → *bekommen* (kein ge-)."},
 {lvl:"m", type:"fill", q:"Partizip II von *anrufen*?", accept:["angerufen"], explain:"Trennbar: an-ge-rufen → *angerufen*."},
 {lvl:"h", type:"transform", q:"Setze ins Perfekt: „Wir bleiben zu Hause.“", accept:["Wir sind zu Hause geblieben","sind zu Hause geblieben"], explain:"*bleiben* nimmt immer *sein* (Ausnahme ohne Bewegung)."},
 {lvl:"h", type:"mc", q:"Er hat mir sein Auto ___.", options:["geliehen","geleiht","gelehnt","geliehnt"], answer:"geliehen", explain:"leihen → *geliehen* (stark), mit haben."},
 {lvl:"h", type:"fill", q:"Partizip II von *verstehen*?", accept:["verstanden"], explain:"Untrennbar + stark → *verstanden* (kein ge-)."},
 {lvl:"h", type:"mc", q:"Sie ___ nach München umgezogen.", options:["ist","hat","war","wurde"], answer:"ist", explain:"*umziehen* = Ortswechsel → *sein*: 'ist umgezogen'."},
 {lvl:"h", type:"transform", q:"Setze ins Perfekt: „Ich rufe meine Mutter an.“", accept:["Ich habe meine Mutter angerufen","habe meine Mutter angerufen"], explain:"anrufen → angerufen, mit *haben*."},
 {lvl:"h", type:"fill", q:"Partizip II von *nachdenken*?", accept:["nachgedacht"], explain:"Trennbar + Mischverb: nach-ge-dacht → *nachgedacht*."},
 {lvl:"h", type:"mc", q:"Es ___ den ganzen Tag geregnet.", options:["hat","ist","war","wurde"], answer:"hat", explain:"*regnen* bildet das Perfekt mit *haben*: 'Es hat geregnet.'"},
]);

add("praeteritum",
 "Präteritum = einfache Vergangenheit (Erzählungen/Texte). Bei *sein, haben* und Modalverben auch beim Sprechen. Schwach: Stamm + -te (machte). Stark: Vokalwechsel (ging, sprach, fuhr). Wichtige: sein→*war*, haben→*hatte*, werden→*wurde*, können→*konnte*.",
[
 {lvl:"e", type:"fill", q:"Präteritum von *sein* (ich): Ich ___ krank.", accept:["war"], explain:"sein → ich/er *war*."},
 {lvl:"e", type:"fill", q:"Präteritum von *haben* (ich): Ich ___ keine Zeit.", accept:["hatte"], explain:"haben → ich/er *hatte*."},
 {lvl:"e", type:"fill", q:"Präteritum von *sein* (wir): Wir ___ müde.", accept:["waren"], explain:"sein → wir/sie *waren*."},
 {lvl:"e", type:"mc", q:"Als Kind ___ ich oft im Park.", options:["spielte","spielt","gespielt","spielten"], answer:"spielte", explain:"Schwach, 1. Person Singular → *spielte*."},
 {lvl:"e", type:"fill", q:"Präteritum von *haben* (sie, Plural): Sie ___ Hunger.", accept:["hatten"], explain:"haben → sie *hatten*."},
 {lvl:"e", type:"mc", q:"Es ___ sehr kalt.", options:["war","wart","waren","ist"], answer:"war", explain:"sein → es *war*."},
 {lvl:"m", type:"fill", q:"Präteritum von *gehen* (er): Er ___ nach Hause.", accept:["ging"], explain:"Stark: gehen → *ging*."},
 {lvl:"m", type:"fill", q:"Präteritum von *fahren* (wir): Wir ___ ans Meer.", accept:["fuhren"], explain:"Stark a→u: fahren → wir *fuhren*."},
 {lvl:"m", type:"fill", q:"Präteritum von *können* (ich): Ich ___ nicht kommen.", accept:["konnte"], explain:"Modalverb → *konnte* (ohne Umlaut)."},
 {lvl:"m", type:"fill", q:"Präteritum von *sprechen* (sie, Sg.): Sie ___ leise.", accept:["sprach"], explain:"Stark e→a: sprechen → *sprach*."},
 {lvl:"m", type:"transform", q:"Setze ins Präteritum: „Ich kaufe Brot.“", accept:["Ich kaufte Brot","kaufte Brot"], explain:"Schwach: kaufen → *kaufte*."},
 {lvl:"m", type:"fill", q:"Präteritum von *werden* (es): Es ___ dunkel.", accept:["wurde"], explain:"werden → *wurde*."},
 {lvl:"m", type:"fill", q:"Präteritum von *kommen* (er): Er ___ zu spät.", accept:["kam"], explain:"Stark: kommen → *kam*."},
 {lvl:"m", type:"fill", q:"Präteritum von *geben* (es): Es ___ viel zu tun.", accept:["gab"], explain:"Stark: geben → *gab* ('es gab')."},
 {lvl:"h", type:"fill", q:"Präteritum von *nehmen* (er): Er ___ den Bus.", accept:["nahm"], explain:"Stark, unregelmäßig: nehmen → *nahm*."},
 {lvl:"h", type:"fill", q:"Präteritum von *finden* (ich): Ich ___ den Film gut.", accept:["fand"], explain:"Stark: finden → *fand*."},
 {lvl:"h", type:"fill", q:"Präteritum von *bringen* (sie, Sg.): Sie ___ mir Blumen.", accept:["brachte"], explain:"Mischverb: bringen → *brachte*."},
 {lvl:"h", type:"fill", q:"Präteritum von *denken* (ich): Ich ___ an dich.", accept:["dachte"], explain:"Mischverb: denken → *dachte*."},
 {lvl:"h", type:"fill", q:"Präteritum von *wissen* (er): Er ___ die Antwort nicht.", accept:["wusste"], explain:"Unregelmäßig: wissen → *wusste*."},
 {lvl:"h", type:"transform", q:"Setze ins Präteritum: „Sie liest ein Buch.“", accept:["Sie las ein Buch","las ein Buch"], explain:"Stark: lesen → *las*."},
]);

add("kausal",
 "Wortstellung! *weil, obwohl, da* → Verb ans *Satzende*. *denn* → normale Wortstellung (Verb Position 2). *deshalb/deswegen/darum/trotzdem* → Position 1 + Inversion ('deshalb *bleibe ich*'). *nämlich* steht im Mittelfeld ('Ich bin *nämlich* krank').",
[
 {lvl:"e", type:"mc", q:"Warum lernst du Deutsch? – ___", options:["Weil es mir Spaß macht.","Weil es macht mir Spaß."], answer:"Weil es mir Spaß macht.", explain:"Nach *weil* steht das Verb am Ende: '…Spaß *macht*.'"},
 {lvl:"e", type:"mc", q:"Es ist kalt. ___ ziehe ich eine Jacke an.", options:["Deshalb","Weil","Obwohl","Denn"], answer:"Deshalb", explain:"Grund→Folge zwischen zwei Hauptsätzen → *deshalb* + Inversion."},
 {lvl:"e", type:"mc", q:"Ich bleibe zu Hause, ___ ich krank bin.", options:["weil","deshalb","trotzdem","denn"], answer:"weil", explain:"Grund im Nebensatz ('ich krank *bin*') → *weil*."},
 {lvl:"e", type:"mc", q:"Ich bin müde. ___ gehe ich ins Bett.", options:["Deshalb","Weil","Obwohl","Denn"], answer:"Deshalb", explain:"Folge → *deshalb* + Inversion ('gehe ich')."},
 {lvl:"e", type:"mc", q:"Ich lerne viel, ___ ich will die Prüfung bestehen.", options:["denn","weil","deshalb","obwohl"], answer:"denn", explain:"'ich will' (normale Wortstellung) → *denn*."},
 {lvl:"m", type:"mc", q:"Welcher Satz ist richtig?", options:["Ich lerne Deutsch, weil ich in Deutschland arbeiten will.","Ich lerne Deutsch, weil ich will in Deutschland arbeiten."], answer:"Ich lerne Deutsch, weil ich in Deutschland arbeiten will.", explain:"Nach *weil* steht das konjugierte Verb ganz am Ende."},
 {lvl:"m", type:"mc", q:"Es regnet, ___ ich nehme einen Schirm mit.", options:["denn","weil","deshalb","obwohl"], answer:"denn", explain:"'ich nehme' bleibt normal → *denn*."},
 {lvl:"m", type:"mc", q:"Es regnet, ___ nehme ich einen Schirm mit.", options:["deshalb","denn","weil","obwohl"], answer:"deshalb", explain:"'nehme ich' (Inversion) → Adverb *deshalb* auf Position 1."},
 {lvl:"m", type:"mc", q:"___ es sehr kalt ist, gehe ich schwimmen.", options:["Obwohl","Weil","Denn","Deshalb"], answer:"Obwohl", explain:"Gegensatz (kalt, trotzdem schwimmen) → *obwohl* (Verb am Ende)."},
 {lvl:"m", type:"mc", q:"Es ist sehr kalt. ___ gehe ich schwimmen.", options:["Trotzdem","Weil","Obwohl","Denn"], answer:"Trotzdem", explain:"Gegensatz zwischen zwei Hauptsätzen → *trotzdem* + Inversion."},
 {lvl:"m", type:"transform", q:"Verbinde mit *weil*: „Ich gehe nicht mit. Ich habe keine Zeit.“", accept:["Ich gehe nicht mit, weil ich keine Zeit habe","weil ich keine Zeit habe"], explain:"weil → Verb ans Ende: '…, weil ich keine Zeit *habe*.'"},
 {lvl:"m", type:"mc", q:"Sie hat viel gelernt, ___ hat sie die Prüfung nicht bestanden.", options:["trotzdem","deshalb","weil","damit"], answer:"trotzdem", explain:"Unerwarteter Gegensatz → *trotzdem*."},
 {lvl:"m", type:"mc", q:"Wir bleiben drinnen, ___ es draußen stark regnet.", options:["weil","denn","deshalb","trotzdem"], answer:"weil", explain:"'es stark *regnet*' – Verb am Ende → *weil*."},
 {lvl:"m", type:"fill", q:"Ich konnte nicht kommen, weil mein Auto kaputt ___.", accept:["war"], explain:"weil → Verb ans Ende; sein Präteritum = *war*."},
 {lvl:"h", type:"transform", q:"Verbinde mit *obwohl*: „Er ist reich. Er ist nicht glücklich.“", accept:["Obwohl er reich ist, ist er nicht glücklich","Er ist nicht glücklich, obwohl er reich ist","obwohl er reich ist"], explain:"obwohl → Verb ans Ende: 'Obwohl er reich *ist*, …'"},
 {lvl:"h", type:"transform", q:"Verbinde mit *deshalb*: „Ich habe Hunger. Ich mache mir ein Brot.“", accept:["Ich habe Hunger, deshalb mache ich mir ein Brot","deshalb mache ich mir ein Brot"], explain:"deshalb → Inversion: '…, deshalb *mache ich* …'"},
 {lvl:"h", type:"mc", q:"___ ich sehr müde war, arbeitete ich weiter.", options:["Obwohl","Weil","Denn","Deshalb"], answer:"Obwohl", explain:"Einräumung (müde – trotzdem weiter) → *obwohl*."},
 {lvl:"h", type:"mc", q:"Ich spare Geld, ___ ich gerade wenig verdiene.", options:["weil","deshalb","denn","trotzdem"], answer:"weil", explain:"'ich … *verdiene*' (Verb am Ende) → *weil*."},
 {lvl:"h", type:"mc", q:"Er kam zu spät, ___ war der Chef verärgert.", options:["deshalb","weil","obwohl","denn"], answer:"deshalb", explain:"Folge mit Inversion ('war der Chef') → *deshalb*."},
 {lvl:"h", type:"mc", q:"___ es schon spät war, gingen wir nach Hause.", options:["Da","Denn","Deshalb","Trotzdem"], answer:"Da", explain:"*da* = weil (Grund), oft am Satzanfang; Verb am Ende ('spät *war*')."},
 {lvl:"h", type:"mc", q:"Ich kann leider nicht kommen. Ich bin ___ krank.", options:["nämlich","weil","denn","obwohl"], answer:"nämlich", explain:"*nämlich* gibt einen Grund und steht im Mittelfeld (nie am Satzanfang)."},
]);

add("temporal",
 "Temporale Nebensätze (Verb am Ende!): *als* = einmal in der Vergangenheit; *wenn* = wiederholt / Gegenwart / Zukunft; *während* = gleichzeitig; *nachdem* = danach (oft Plusquamperfekt); *bevor* = vorher; *seit(dem)* = seit; *bis* = bis; *sobald* = sofort danach; *wann* = indirekte Frage.",
[
 {lvl:"e", type:"mc", q:"___ ich gestern nach Hause kam, war niemand da.", options:["Als","Wenn","Wann","Ob"], answer:"Als", explain:"Einmaliges Ereignis in der Vergangenheit → *als*."},
 {lvl:"e", type:"mc", q:"Immer ___ es regnet, bleibe ich zu Hause.", options:["wenn","als","wann","während"], answer:"wenn", explain:"Wiederholte Handlung ('immer …') → *wenn*."},
 {lvl:"e", type:"mc", q:"___ ich klein war, wohnten wir in Köln.", options:["Als","Wenn","Wann","Bis"], answer:"Als", explain:"Vergangener Zeitraum, einmalig → *als*."},
 {lvl:"e", type:"mc", q:"Ich frühstücke, ___ ich zur Arbeit gehe.", options:["bevor","nachdem","seit","bis"], answer:"bevor", explain:"Erst frühstücken, dann Arbeit → *bevor* (vorher)."},
 {lvl:"e", type:"mc", q:"Weißt du, ___ der Zug abfährt?", options:["wann","wenn","als","ob"], answer:"wann", explain:"Indirekte Frage nach der Zeit → *wann*."},
 {lvl:"m", type:"fill", q:"___ du fertig bist, ruf mich bitte an. (= sofort danach)", accept:["Sobald"], explain:"'sofort danach' → *sobald* (Verb am Ende)."},
 {lvl:"m", type:"mc", q:"Ich putze mir die Zähne, ___ ich ins Bett gehe.", options:["bevor","nachdem","während","seit"], answer:"bevor", explain:"Vorher → *bevor*."},
 {lvl:"m", type:"mc", q:"___ ich in Deutschland wohne, spreche ich viel besser Deutsch.", options:["Seitdem","Bevor","Bis","Als"], answer:"Seitdem", explain:"Ab einem Zeitpunkt bis jetzt → *seitdem*."},
 {lvl:"m", type:"transform", q:"Verbinde mit *während*: „Ich koche. Ich höre Musik.“", accept:["Während ich koche, höre ich Musik","während ich koche"], explain:"Gleichzeitig → *während*; Verb ans Ende."},
 {lvl:"m", type:"mc", q:"Warte bitte hier, ___ ich zurückkomme.", options:["bis","seit","als","ob"], answer:"bis", explain:"Endpunkt der Handlung → *bis*."},
 {lvl:"m", type:"mc", q:"___ das Konzert zu Ende war, gingen alle nach Hause.", options:["Als","Wenn","Während","Bis"], answer:"Als", explain:"Einmaliges Ereignis (Vergangenheit) → *als*."},
 {lvl:"m", type:"mc", q:"Ich höre gern Musik, ___ ich koche.", options:["während","nachdem","bevor","seit"], answer:"während", explain:"Zwei gleichzeitige Handlungen → *während*."},
 {lvl:"h", type:"mc", q:"Nachdem er gegessen ___, ging er spazieren.", options:["hatte","hat","war","ist"], answer:"hatte", explain:"Nach *nachdem* + Vergangenheit → *Plusquamperfekt* ('hatte gegessen')."},
 {lvl:"h", type:"mc", q:"Welcher Satz ist korrekt?", options:["Nachdem ich gegessen hatte, putzte ich die Küche.","Nachdem ich hatte gegessen, ich putzte die Küche."], answer:"Nachdem ich gegessen hatte, putzte ich die Küche.", explain:"Nebensatz: Verb am Ende ('gegessen hatte'); Hauptsatz beginnt mit dem Verb ('putzte ich')."},
 {lvl:"h", type:"mc", q:"___ ich die Arbeit beendet hatte, machte ich eine Pause.", options:["Nachdem","Bevor","Während","Seit"], answer:"Nachdem", explain:"Zuerst beenden (Plusquamperfekt), dann Pause → *nachdem*."},
 {lvl:"h", type:"mc", q:"Bevor ich einkaufen ___, schreibe ich eine Liste.", options:["gehe","gehen","gegangen","zu gehen"], answer:"gehe", explain:"Nebensatz mit *bevor*: Verb am Ende, hier Präsens → 'gehe'."},
 {lvl:"h", type:"mc", q:"Jedes Mal, ___ ich ihn sah, lächelte er.", options:["wenn","als","wann","ob"], answer:"wenn", explain:"'jedes Mal wenn' = wiederholt (auch in der Vergangenheit!) → *wenn*, nicht als."},
 {lvl:"h", type:"mc", q:"Sie rief mich an, ___ sie angekommen war.", options:["nachdem","bevor","während","bis"], answer:"nachdem", explain:"Ankommen war zuerst (Plusquamperfekt) → *nachdem*."},
]);

add("zweiteilig",
 "Zweiteilige Konnektoren: *entweder … oder* (eins von beiden), *weder … noch* (keins), *nicht nur … sondern auch*, *sowohl … als auch* (beides), *zwar … aber* (Einräumung), *je … desto/umso* (Verhältnis + Komparativ).",
[
 {lvl:"e", type:"mc", q:"Ich trinke ___ Kaffee ___ Tee – beides mag ich nicht.", options:["weder … noch","entweder … oder","sowohl … als auch","zwar … aber"], answer:"weder … noch", explain:"'keins von beiden' → *weder … noch*."},
 {lvl:"e", type:"mc", q:"Du kannst ___ mit dem Bus ___ mit dem Zug fahren.", options:["entweder … oder","weder … noch","nicht nur … sondern","je … desto"], answer:"entweder … oder", explain:"Auswahl zwischen zwei Möglichkeiten → *entweder … oder*."},
 {lvl:"e", type:"mc", q:"Sie spricht ___ Englisch ___ Französisch fließend.", options:["sowohl … als auch","weder … noch","entweder … oder","zwar … aber"], answer:"sowohl … als auch", explain:"Beides (positiv) → *sowohl … als auch*."},
 {lvl:"e", type:"mc", q:"Nimm ___ den roten ___ den blauen Schal.", options:["entweder … oder","weder … noch","zwar … aber","je … desto"], answer:"entweder … oder", explain:"Auswahl → *entweder … oder*."},
 {lvl:"m", type:"mc", q:"Er ist ___ intelligent, ___ auch sehr fleißig.", options:["nicht nur … sondern","weder … noch","entweder … oder","je … desto"], answer:"nicht nur … sondern", explain:"Steigerung → *nicht nur … sondern auch*."},
 {lvl:"m", type:"mc", q:"___ mehr ich lerne, ___ besser verstehe ich.", options:["Je … desto","Sowohl … als auch","Entweder … oder","Zwar … aber"], answer:"Je … desto", explain:"Verhältnis → *je … desto* (+ Komparativ)."},
 {lvl:"m", type:"mc", q:"___ ist er reich, ___ ist er nicht glücklich.", options:["Zwar … aber","Weder … noch","Je … desto","Sowohl … als auch"], answer:"Zwar … aber", explain:"Einräumung + Gegensatz → *zwar … aber*."},
 {lvl:"m", type:"mc", q:"Ich habe heute ___ Zeit ___ Lust auf die Party.", options:["weder … noch","entweder … oder","sowohl … als auch","nicht nur … sondern"], answer:"weder … noch", explain:"Beides verneint → *weder … noch*."},
 {lvl:"m", type:"fill", q:"Je mehr man übt, ___ ___ wird man. (gut)", accept:["desto besser","umso besser"], explain:"Nach *je* folgt *desto* (oder *umso*) + Komparativ."},
 {lvl:"m", type:"mc", q:"Nicht nur die Kinder, ___ auch die Eltern haben Spaß.", options:["sondern","aber","oder","denn"], answer:"sondern", explain:"'nicht nur … *sondern* auch'."},
 {lvl:"h", type:"mc", q:"Welcher Satz ist korrekt?", options:["Je älter ich werde, desto ruhiger werde ich.","Je älter werde ich, desto ruhiger ich werde."], answer:"Je älter ich werde, desto ruhiger werde ich.", explain:"Nach *je* Verb ans Ende ('werde'), nach *desto* Inversion (Komparativ + Verb + Subjekt)."},
 {lvl:"h", type:"mc", q:"Er kann ___ singen ___ tanzen – ein echtes Talent!", options:["sowohl … als auch","weder … noch","zwar … aber","je … desto"], answer:"sowohl … als auch", explain:"Beide Fähigkeiten (positiv) → *sowohl … als auch*."},
 {lvl:"h", type:"mc", q:"Das Wetter war ___ schlecht, ___ wir hatten trotzdem Spaß.", options:["zwar … aber","weder … noch","je … desto","sowohl … als auch"], answer:"zwar … aber", explain:"Einräumung + Gegensatz → *zwar … aber*."},
 {lvl:"h", type:"fill", q:"Je schneller du fährst, ___ ___ ist es. (gefährlich)", accept:["desto gefährlicher","umso gefährlicher"], explain:"je … *desto/umso* + Komparativ von gefährlich → gefährlicher."},
 {lvl:"h", type:"mc", q:"Entweder du entschuldigst dich, ___ ich gehe.", options:["oder","noch","aber","sondern"], answer:"oder", explain:"'entweder … *oder*' (die zweite Möglichkeit)."},
 {lvl:"h", type:"mc", q:"Ich weiß nicht, ob ich ___ Zeit ___ Geld dafür habe.", options:["weder … noch","entweder … oder","sowohl … als auch","zwar … aber"], answer:"weder … noch", explain:"Beides fehlt (verneint) → *weder … noch*."},
]);

add("wechsel",
 "Wechselpräpositionen (an, auf, hinter, in, neben, über, unter, vor, zwischen): *Wo?* (Ort) → *Dativ*; *Wohin?* (Bewegung) → *Akkusativ*. liegen/stehen/sein = Dativ; legen/stellen/gehen = Akkusativ. Kurzformen: in+das=*ins*, in+dem=*im*, an+das=*ans*, an+dem=*am*.",
[
 {lvl:"e", type:"mc", q:"Das Buch liegt auf ___ Tisch. (der Tisch)", options:["dem","den","der","das"], answer:"dem", explain:"'liegen' = Ort → *Dativ*: auf *dem* Tisch."},
 {lvl:"e", type:"mc", q:"Ich lege das Buch auf ___ Tisch.", options:["den","dem","der","das"], answer:"den", explain:"'legen' = Bewegung → *Akkusativ*: auf *den* Tisch."},
 {lvl:"e", type:"mc", q:"Wir sind gerade ___ Kino.", options:["im","ins","in das","zum"], answer:"im", explain:"Ort (Wo?) → Dativ; in+dem = *im*."},
 {lvl:"e", type:"mc", q:"Der Ball liegt ___ dem Tisch (darunter).", options:["unter","über","auf","neben"], answer:"unter", explain:"'darunter' → Präposition *unter*."},
 {lvl:"e", type:"mc", q:"„Ich bin im Garten.“ – Wo oder Wohin?", options:["Wo? (Dativ)","Wohin? (Akkusativ)"], answer:"Wo? (Dativ)", explain:"Kein Bewegungsziel → Ort → *Wo? (Dativ)*."},
 {lvl:"m", type:"mc", q:"Wir gehen heute Abend ___ Kino.", options:["ins","im","in dem","zum"], answer:"ins", explain:"Bewegung (Wohin?) → Akkusativ; in+das = *ins*."},
 {lvl:"m", type:"mc", q:"Die Lampe hängt an ___ Decke. (die Decke)", options:["der","die","dem","den"], answer:"der", explain:"'hängen' (Ort) → Dativ, feminin: an *der* Decke."},
 {lvl:"m", type:"fill", q:"Ich hänge das Bild an ___ Wand. (die Wand, Bewegung)", accept:["die"], explain:"'hängen' mit Bewegung (Wohin?) → Akkusativ: an *die* Wand."},
 {lvl:"m", type:"mc", q:"Die Katze sitzt ___ dem Stuhl und dem Tisch.", options:["zwischen","unter","neben","über"], answer:"zwischen", explain:"'zwischen' zwei Dingen; Ort → Dativ."},
 {lvl:"m", type:"mc", q:"Stell die Flasche in ___ Kühlschrank. (der Kühlschrank)", options:["den","dem","der","das"], answer:"den", explain:"'stellen' = Bewegung → Akkusativ: in *den* Kühlschrank."},
 {lvl:"m", type:"mc", q:"Das Auto steht vor ___ Haus. (das Haus)", options:["dem","das","den","der"], answer:"dem", explain:"'stehen' = Ort → Dativ, neutrum: vor *dem* Haus."},
 {lvl:"m", type:"mc", q:"Häng deine Jacke an ___ Haken. (der Haken, Wohin?)", options:["den","dem","der","das"], answer:"den", explain:"Bewegung (Wohin?) → Akkusativ: an *den* Haken."},
 {lvl:"m", type:"mc", q:"Die Kinder laufen ___ die Straße.", options:["über","auf","an","bei"], answer:"über", explain:"'über die Straße laufen' = Bewegung → *über* + Akkusativ."},
 {lvl:"h", type:"mc", q:"Die Maus läuft schnell hinter ___ Schrank. (der Schrank, Wohin?)", options:["den","dem","der","das"], answer:"den", explain:"Bewegung → Akkusativ, maskulin: hinter *den* Schrank."},
 {lvl:"h", type:"mc", q:"Der Schlüssel steckt ___ Tür.", options:["in der","in die","an der","auf der"], answer:"in der", explain:"Ort (Wo? steckt) → Dativ, feminin: *in der* Tür."},
 {lvl:"h", type:"mc", q:"Ich stelle die Vase ___ Fensterbrett. (das)", options:["auf das","auf dem","an das","an dem"], answer:"auf das", explain:"'stellen' = Bewegung → Akkusativ, neutrum: *auf das* Fensterbrett."},
 {lvl:"h", type:"mc", q:"___ den Wolken scheint immer die Sonne. (die Wolken, Ort)", options:["Über","Auf","An","Zwischen"], answer:"Über", explain:"Ort über etwas → *über*; 'über den Wolken' (Dativ Plural, Wo?)."},
 {lvl:"h", type:"mc", q:"Sie geht ___ Wohnzimmer und setzt sich. (das Wohnzimmer)", options:["ins","im","in dem","beim"], answer:"ins", explain:"Bewegung (Wohin?) → Akkusativ; in+das = *ins*."},
 {lvl:"h", type:"mc", q:"„Er springt ins Wasser.“ – welcher Fall und warum?", options:["Akkusativ – Bewegung (Wohin?)","Dativ – Ort (Wo?)"], answer:"Akkusativ – Bewegung (Wohin?)", explain:"'springen ins Wasser' = Richtung → *Akkusativ* (ins = in das)."},
]);

add("praep",
 "Feste Fälle: *Akkusativ* → durch, für, gegen, ohne, um. *Dativ* → aus, bei, mit, nach, seit, von, zu, gegenüber. *Genitiv* → wegen, trotz, während, (an)statt, aufgrund, innerhalb, außerhalb. Idiome: *zu* Hause (Ort), *nach* Hause (Richtung); zu+dem = *zum*, zu+der = *zur*.",
[
 {lvl:"e", type:"mc", q:"Wir fahren mit ___ Bus. (der Bus)", options:["dem","den","der","das"], answer:"dem", explain:"*mit* + Dativ; maskulin → mit *dem* Bus."},
 {lvl:"e", type:"mc", q:"Ich mache das für ___ Freund. (der Freund)", options:["meinen","meinem","meines","mein"], answer:"meinen", explain:"*für* + Akkusativ; maskulin → *meinen*."},
 {lvl:"e", type:"mc", q:"Nach ___ Arbeit gehe ich schwimmen. (die Arbeit)", options:["der","die","dem","den"], answer:"der", explain:"*nach* + Dativ; feminin → nach *der* Arbeit."},
 {lvl:"e", type:"mc", q:"Ich komme gerade aus ___ Schule. (die Schule)", options:["der","die","dem","den"], answer:"der", explain:"*aus* + Dativ; feminin → aus *der* Schule."},
 {lvl:"e", type:"mc", q:"Ich bin schon ___ Hause.", options:["zu","nach","bei","in"], answer:"zu", explain:"'*zu* Hause' = zuhause sein (Ort)."},
 {lvl:"m", type:"mc", q:"Ich gehe ohne ___ Bruder ins Kino. (der Bruder)", options:["meinen","meinem","mein","meines"], answer:"meinen", explain:"*ohne* + Akkusativ; maskulin → *meinen*."},
 {lvl:"m", type:"mc", q:"Das Café ist gegenüber ___ Bahnhof. (der Bahnhof)", options:["dem","den","des","der"], answer:"dem", explain:"*gegenüber* + Dativ → gegenüber *dem* Bahnhof."},
 {lvl:"m", type:"mc", q:"Wir gehen durch ___ Park. (der Park)", options:["den","dem","des","der"], answer:"den", explain:"*durch* + Akkusativ; maskulin → durch *den* Park."},
 {lvl:"m", type:"mc", q:"Seit ___ Woche lerne ich Gitarre. (eine Woche)", options:["einer","eine","einem","eines"], answer:"einer", explain:"*seit* + Dativ; feminin → seit *einer* Woche."},
 {lvl:"m", type:"mc", q:"Ich fahre jetzt ___ Hause.", options:["nach","zu","bei","in"], answer:"nach", explain:"'*nach* Hause' = nach Hause gehen/fahren (Richtung)."},
 {lvl:"m", type:"mc", q:"Ich wohne noch ___ meinen Eltern.", options:["bei","mit","zu","von"], answer:"bei", explain:"*bei* + Dativ = im Haus von jemandem wohnen."},
 {lvl:"m", type:"mc", q:"Ich gehe morgen ___ Arzt. (der Arzt)", options:["zum","zur","zu den","beim"], answer:"zum", explain:"*zu* + Dativ; zu+dem = *zum* Arzt."},
 {lvl:"h", type:"mc", q:"___ des schlechten Wetters bleiben wir zu Hause.", options:["Wegen","Ohne","Seit","Für"], answer:"Wegen", explain:"*wegen* + Genitiv ('des … Wetters') = aus welchem Grund."},
 {lvl:"h", type:"mc", q:"Während ___ Ferien war ich in Italien. (die Ferien, Plural)", options:["der","den","die","des"], answer:"der", explain:"*während* + Genitiv; Plural → während *der* Ferien."},
 {lvl:"h", type:"mc", q:"Trotz ___ Regens spielten die Kinder weiter. (der Regen)", options:["des","dem","den","der"], answer:"des", explain:"*trotz* + Genitiv; maskulin → trotz *des* Regens."},
 {lvl:"h", type:"mc", q:"Statt ___ Kaffees trinke ich heute Tee. (der Kaffee)", options:["des","dem","den","der"], answer:"des", explain:"*statt* + Genitiv; maskulin → statt *des* Kaffees."},
 {lvl:"h", type:"mc", q:"Aufgrund ___ Unfalls kam der Zug zu spät. (der Unfall)", options:["des","dem","den","der"], answer:"des", explain:"*aufgrund* + Genitiv; maskulin → *des* Unfalls."},
 {lvl:"h", type:"mc", q:"Innerhalb ___ Woche bekommen Sie eine Antwort. (eine Woche)", options:["einer","eine","einem","eines"], answer:"einer", explain:"*innerhalb* + Genitiv; feminin → innerhalb *einer* Woche."},
]);

add("adjektiv",
 "Adjektivendung = Artikel + Fall + Genus. Nach *bestimmtem* Artikel (der/die/das) → schwach: Nom -e, sonst meist -en. Nach *ein/kein/mein* → gemischt: Nom m -er, n -es, f -e. *Ohne* Artikel → stark: Nom m -er, n -es, f/Pl -e; Dativ -em/-er/-en; Genitiv m/n -en.",
[
 {lvl:"e", type:"mc", q:"Der ___ Mann liest Zeitung. (alt)", options:["alte","alter","alten","altes"], answer:"alte", explain:"Nach *der*, Nominativ maskulin → *-e*: der alte Mann."},
 {lvl:"e", type:"mc", q:"Die ___ Frau kommt aus Wien. (jung)", options:["junge","jungen","junger","junges"], answer:"junge", explain:"Nach *die*, Nominativ feminin → *-e*: die junge Frau."},
 {lvl:"e", type:"mc", q:"Das ___ Auto ist teuer. (neu)", options:["neue","neuer","neuen","neues"], answer:"neue", explain:"Nach *das*, Nominativ neutrum → *-e*: das neue Auto."},
 {lvl:"e", type:"mc", q:"Ich sehe den ___ Mann. (alt)", options:["alten","alte","alter","altes"], answer:"alten", explain:"Akkusativ maskulin nach *den* → *-en*."},
 {lvl:"e", type:"mc", q:"Das ist ein ___ Hund. (klein)", options:["kleiner","kleine","kleines","kleinen"], answer:"kleiner", explain:"Nach *ein*, Nominativ maskulin → *-er*: ein kleiner Hund."},
 {lvl:"m", type:"mc", q:"Das ist ein ___ Auto. (neu)", options:["neues","neue","neuer","neuen"], answer:"neues", explain:"Nach *ein*, Nominativ neutrum → *-es*: ein neues Auto."},
 {lvl:"m", type:"mc", q:"Ich habe eine ___ Idee! (gut)", options:["gute","guten","guter","gutes"], answer:"gute", explain:"Nach *eine*, Akkusativ feminin → *-e*: eine gute Idee."},
 {lvl:"m", type:"mc", q:"Ich fahre mit dem ___ Auto. (neu)", options:["neuen","neue","neues","neuem"], answer:"neuen", explain:"Dativ nach *dem* → *-en*: mit dem neuen Auto."},
 {lvl:"m", type:"mc", q:"Die ___ Kinder spielen im Garten. (klein)", options:["kleinen","kleine","kleiner","kleines"], answer:"kleinen", explain:"Nach *die* (Plural, bestimmt) → *-en*."},
 {lvl:"m", type:"mc", q:"Er wohnt in einem ___ Haus. (groß)", options:["großen","großes","großem","große"], answer:"großen", explain:"Dativ neutrum nach *einem* → *-en*: in einem großen Haus."},
 {lvl:"m", type:"mc", q:"Ich trinke gern ___ Kaffee. (schwarz — kein Artikel)", options:["schwarzen","schwarzer","schwarzes","schwarze"], answer:"schwarzen", explain:"Ohne Artikel, Akkusativ maskulin → stark *-en*: schwarzen Kaffee."},
 {lvl:"m", type:"mc", q:"Heute ist ___ Wetter. (schön — kein Artikel)", options:["schönes","schöne","schöner","schönen"], answer:"schönes", explain:"Ohne Artikel, Nominativ neutrum → stark *-es*: schönes Wetter."},
 {lvl:"h", type:"mc", q:"Ich kaufe ___ Äpfel. (frisch — kein Artikel)", options:["frische","frischen","frischer","frisches"], answer:"frische", explain:"Ohne Artikel, Akkusativ Plural → stark *-e*: frische Äpfel."},
 {lvl:"h", type:"mc", q:"Trotz des ___ Wetters blieben wir drinnen. (schlecht)", options:["schlechten","schlechtes","schlechte","schlechtem"], answer:"schlechten", explain:"Genitiv neutrum nach *des* → *-en*: des schlechten Wetters."},
 {lvl:"h", type:"mc", q:"Das ist das Auto meines ___ Bruders. (alt)", options:["alten","alte","alter","altes"], answer:"alten", explain:"Genitiv maskulin nach *meines* → *-en*: meines alten Bruders."},
 {lvl:"h", type:"mc", q:"Ich möchte ein Glas ___ Wasser. (kalt — kein Artikel)", options:["kaltes","kalten","kalter","kalte"], answer:"kaltes", explain:"Ohne Artikel, Akkusativ neutrum → stark *-es*: kaltes Wasser."},
 {lvl:"h", type:"mc", q:"Ich war gestern mit ___ Freunden unterwegs. (gut — kein Artikel)", options:["guten","gute","guter","gutes"], answer:"guten", explain:"Ohne Artikel, Dativ Plural → stark *-en*: mit guten Freunden."},
 {lvl:"h", type:"mc", q:"Ich helfe der ___ Frau über die Straße. (alt)", options:["alten","alte","alter","altes"], answer:"alten", explain:"Dativ feminin nach *der* → *-en*: der alten Frau."},
 {lvl:"h", type:"mc", q:"Ein ___ Mann wartet an der Tür. (groß)", options:["großer","große","großen","großes"], answer:"großer", explain:"Nach *ein*, Nominativ maskulin → *-er*: ein großer Mann."},
 {lvl:"h", type:"mc", q:"Zum Essen haben wir ___ Wein getrunken. (gut — kein Artikel)", options:["guten","guter","gutes","gute"], answer:"guten", explain:"Ohne Artikel, Akkusativ maskulin → stark *-en*: guten Wein."},
]);

add("komparativ",
 "Komparativ = Adjektiv + *-er* (+ *als*): schneller als. Superlativ = *am …-sten* oder *der/die/das …-ste*. Vergleich gleich: *so … wie*. Unregelmäßig: gut→besser→am besten; viel→mehr→am meisten; gern→lieber→am liebsten; hoch→höher; teuer→teurer. Umlaut: alt→älter, warm→wärmer.",
[
 {lvl:"e", type:"fill", q:"Komparativ von *gut*?", accept:["besser"], explain:"Unregelmäßig: gut → *besser*."},
 {lvl:"e", type:"fill", q:"Komparativ von *viel*?", accept:["mehr"], explain:"Unregelmäßig: viel → *mehr*."},
 {lvl:"e", type:"mc", q:"Berlin ist ___ als München.", options:["größer","am größten","groß","größten"], answer:"größer", explain:"Vergleich mit *als* → Komparativ *größer*."},
 {lvl:"e", type:"fill", q:"Komparativ von *alt*?", accept:["älter"], explain:"Umlaut: alt → *älter*."},
 {lvl:"e", type:"fill", q:"Komparativ von *schön*?", accept:["schöner"], explain:"Regelmäßig: schön → *schöner*."},
 {lvl:"m", type:"fill", q:"Superlativ von *gut* (am …)?", accept:["am besten"], explain:"gut → besser → *am besten*."},
 {lvl:"m", type:"fill", q:"Ich trinke ___ Tee als Kaffee. (gern, Komparativ)", accept:["lieber"], explain:"gern → *lieber* → am liebsten."},
 {lvl:"m", type:"mc", q:"Der Mount Everest ist der ___ Berg der Welt. (hoch)", options:["höchste","hohe","höher","am höchsten"], answer:"höchste", explain:"Superlativ vor dem Nomen mit Artikel → der *höchste* Berg."},
 {lvl:"m", type:"mc", q:"Im Sommer ist es ___ als im Winter. (warm)", options:["wärmer","warmer","am wärmsten","wärmste"], answer:"wärmer", explain:"Komparativ mit Umlaut: warm → *wärmer*."},
 {lvl:"m", type:"mc", q:"Von allen Läufern ist Anna ___.", options:["am schnellsten","schneller","die schnellere","schnellsten"], answer:"am schnellsten", explain:"Superlativ ohne Nomen (prädikativ) → *am schnellsten*."},
 {lvl:"m", type:"fill", q:"Superlativ von *gern* (am …)?", accept:["am liebsten"], explain:"gern → lieber → *am liebsten*."},
 {lvl:"m", type:"fill", q:"Superlativ von *viel* (am …)?", accept:["am meisten"], explain:"viel → mehr → *am meisten*."},
 {lvl:"h", type:"mc", q:"Das ist mein ___ Freund. (gut, Superlativ)", options:["bester","beste","bestes","am besten"], answer:"bester", explain:"Superlativ vor dem Nomen nach *mein* (mask.) → mein *bester* Freund."},
 {lvl:"h", type:"mc", q:"Er ist genauso groß ___ ich.", options:["wie","als","denn","wenn"], answer:"wie", explain:"Gleichheit → *so … wie* (genauso groß *wie*)."},
 {lvl:"h", type:"mc", q:"Welcher Satz ist korrekt?", options:["Er ist älter als ich.","Er ist älter wie ich."], answer:"Er ist älter als ich.", explain:"Beim Komparativ steht *als*, nicht 'wie'."},
 {lvl:"h", type:"mc", q:"Das ist die ___ Stadt Deutschlands. (groß, Superlativ)", options:["größte","größere","am größten","größten"], answer:"größte", explain:"Superlativ vor dem Nomen, feminin → die *größte* Stadt."},
 {lvl:"h", type:"fill", q:"Komparativ von *hoch*?", accept:["höher"], explain:"Unregelmäßig: hoch → *höher* (das c fällt weg)."},
 {lvl:"h", type:"fill", q:"Komparativ von *teuer*?", accept:["teurer"], explain:"teuer → *teurer* (das e vor r fällt weg)."},
 {lvl:"h", type:"fill", q:"Superlativ von *hoch* (am …)?", accept:["am höchsten"], explain:"hoch → höher → *am höchsten*."},
]);

add("relativ",
 "Relativpronomen: *Genus & Numerus* vom Bezugswort, *Fall* von der Rolle im Relativsatz. der/die/das/die(Pl); Dativ Plural = *denen*; Genitiv = *dessen* (m/n) bzw. *deren* (f/Pl). Präposition vor dem Pronomen (mit dem, für die, an dem). Verb am *Ende*.",
[
 {lvl:"e", type:"mc", q:"Der Mann, ___ dort steht, ist mein Lehrer.", options:["der","den","dem","dessen"], answer:"der", explain:"maskulin; Subjekt (er steht) → Nominativ *der*."},
 {lvl:"e", type:"mc", q:"Das ist die Frau, ___ ich gestern getroffen habe.", options:["die","der","den","deren"], answer:"die", explain:"feminin; Akkusativobjekt von 'treffen' → *die*."},
 {lvl:"e", type:"mc", q:"Der Film, ___ wir gesehen haben, war spannend.", options:["den","der","dem","dessen"], answer:"den", explain:"maskulin; Akkusativobjekt → *den*."},
 {lvl:"e", type:"mc", q:"Das Auto, ___ vor dem Haus steht, ist neu.", options:["das","dem","den","dessen"], answer:"das", explain:"neutrum; Subjekt → Nominativ *das*."},
 {lvl:"m", type:"mc", q:"Das Kind, ___ ich ein Geschenk gab, freut sich.", options:["dem","das","den","dessen"], answer:"dem", explain:"neutrum; 'geben' + Dativ → *dem*."},
 {lvl:"m", type:"mc", q:"Die Leute, ___ ich oft helfe, sind nett.", options:["denen","die","der","deren"], answer:"denen", explain:"Plural; 'helfen' + Dativ → *denen*."},
 {lvl:"m", type:"mc", q:"Das Haus, in ___ ich wohne, ist sehr alt.", options:["dem","das","den","der"], answer:"dem", explain:"'in' (Ort) + Dativ, neutrum → *dem*."},
 {lvl:"m", type:"mc", q:"Der Stuhl, auf ___ du sitzt, ist neu.", options:["dem","den","der","das"], answer:"dem", explain:"'auf' (Ort) + Dativ, maskulin → *dem*."},
 {lvl:"m", type:"mc", q:"Kennst du den Mann, mit ___ sie spricht?", options:["dem","den","der","dessen"], answer:"dem", explain:"'mit' + Dativ, maskulin → *dem*."},
 {lvl:"m", type:"mc", q:"Die Stadt, ___ mir am besten gefällt, ist Wien.", options:["die","der","das","deren"], answer:"die", explain:"'die Stadt gefällt mir' – Subjekt → Nominativ feminin *die*."},
 {lvl:"m", type:"mc", q:"Die Bücher, ___ ich gekauft habe, waren teuer.", options:["die","den","denen","deren"], answer:"die", explain:"Plural; Akkusativobjekt → *die*."},
 {lvl:"h", type:"mc", q:"Der Autor, ___ Buch ich lese, ist berühmt.", options:["dessen","der","den","deren"], answer:"dessen", explain:"Besitz, maskulin → Genitiv *dessen*."},
 {lvl:"h", type:"mc", q:"Die Frau, ___ Auto rot ist, wohnt nebenan.", options:["deren","dessen","die","der"], answer:"deren", explain:"Besitz, feminin → Genitiv *deren*."},
 {lvl:"h", type:"mc", q:"Das sind die Kinder, ___ Eltern im Ausland leben.", options:["deren","dessen","die","denen"], answer:"deren", explain:"Besitz, Plural → Genitiv *deren*."},
 {lvl:"h", type:"mc", q:"Der Freund, ___ ich vertraue, wohnt in Berlin.", options:["dem","den","der","dessen"], answer:"dem", explain:"'vertrauen' + Dativ → *dem*."},
 {lvl:"h", type:"mc", q:"Das Thema, über ___ wir sprachen, war spannend.", options:["das","dem","den","dessen"], answer:"das", explain:"'sprechen über' + Akkusativ, neutrum → *das*."},
 {lvl:"h", type:"mc", q:"Die Firma, für ___ ich arbeite, ist international.", options:["die","der","den","deren"], answer:"die", explain:"'für' + Akkusativ, feminin → *die*."},
 {lvl:"h", type:"mc", q:"Der Tag, an ___ wir uns kennenlernten, war schön.", options:["dem","den","der","das"], answer:"dem", explain:"'an' (temporal: an dem Tag) + Dativ, maskulin → *dem*."},
]);

add("konjunktiv",
 "Konjunktiv II für Höflichkeit, irreale Wünsche & Hypothesen. Meist *würde* + Infinitiv. Eigene Formen: sein→*wäre*, haben→*hätte*, können→*könnte*, müssen→*müsste*, werden→würde, wissen→*wüsste*. Vergangenheit: *hätte/wäre* + Partizip II.",
[
 {lvl:"e", type:"mc", q:"Wenn ich mehr Zeit ___, würde ich ein Buch lesen.", options:["hätte","habe","hatte","haben"], answer:"hätte", explain:"Irreale Bedingung → Konjunktiv II von haben: *hätte*."},
 {lvl:"e", type:"fill", q:"Konjunktiv II von *sein* (ich)?", accept:["wäre"], explain:"sein → ich/er *wäre*."},
 {lvl:"e", type:"fill", q:"Konjunktiv II von *haben* (er)?", accept:["hätte"], explain:"haben → ich/er *hätte*."},
 {lvl:"e", type:"mc", q:"___ Sie mir bitte kurz helfen? (sehr höflich)", options:["Könnten","Konnten","Können","Kann"], answer:"Könnten", explain:"Höfliche Bitte → *könnten* Sie …?"},
 {lvl:"e", type:"mc", q:"Ich ___ gern noch einen Kaffee, bitte.", options:["hätte","habe","hatte","haben"], answer:"hätte", explain:"Höflicher Wunsch: 'Ich *hätte* gern …'"},
 {lvl:"m", type:"mc", q:"An deiner Stelle ___ ich zum Arzt gehen.", options:["würde","werde","wurde","würdest"], answer:"würde", explain:"Ratschlag → *würde* + Infinitiv."},
 {lvl:"m", type:"mc", q:"Wenn er reich ___, würde er nicht mehr arbeiten.", options:["wäre","ist","war","sei"], answer:"wäre", explain:"Irreal → Konjunktiv II von sein: *wäre*."},
 {lvl:"m", type:"fill", q:"Ich wünschte, ich ___ mehr Geld. (haben)", accept:["hätte"], explain:"Irrealer Wunsch → 'ich *hätte* mehr Geld.'"},
 {lvl:"m", type:"mc", q:"Wenn ich du ___, würde ich das nicht tun.", options:["wäre","bin","war","sei"], answer:"wäre", explain:"'Wenn ich du *wäre*' – Konjunktiv II von sein."},
 {lvl:"m", type:"fill", q:"Konjunktiv II von *können* (ich)?", accept:["könnte"], explain:"können → ich *könnte*."},
 {lvl:"m", type:"fill", q:"Höflicher: „Hilfst du mir?“ → „___ du mir bitte helfen?“", accept:["Würdest","Könntest"], explain:"Höflich → *Würdest*/​*Könntest* du …?"},
 {lvl:"m", type:"mc", q:"Das ___ ich wirklich nicht gedacht! (Vergangenheit)", options:["hätte","habe","hatte","würde"], answer:"hätte", explain:"Konjunktiv II der Vergangenheit: *hätte* + Partizip II."},
 {lvl:"h", type:"fill", q:"Konjunktiv II von *müssen* (ich)?", accept:["müsste"], explain:"müssen → ich *müsste*."},
 {lvl:"h", type:"fill", q:"Konjunktiv II von *wissen* (ich)?", accept:["wüsste"], explain:"wissen → ich *wüsste*."},
 {lvl:"h", type:"mc", q:"Wenn ich das gewusst ___, wäre ich gekommen.", options:["hätte","habe","hatte","würde"], answer:"hätte", explain:"Irreal in der Vergangenheit → *hätte* + Partizip II ('gewusst hätte')."},
 {lvl:"h", type:"mc", q:"Beinahe ___ ich zu spät gekommen!", options:["wäre","war","bin","hätte"], answer:"wäre", explain:"kommen bildet Perfekt mit sein → Konjunktiv II Vergangenheit: *wäre* … gekommen."},
 {lvl:"h", type:"mc", q:"An seiner Stelle ___ ich das anders gemacht.", options:["hätte","würde","wäre","habe"], answer:"hätte", explain:"Vergangener Ratschlag → *hätte* … gemacht."},
 {lvl:"h", type:"mc", q:"Wenn wir Zeit hätten, ___ wir länger bleiben.", options:["könnten","konnten","können","kann"], answer:"könnten", explain:"Irrealer Hauptsatz → Konjunktiv II von können: *könnten*."},
 {lvl:"h", type:"mc", q:"Er tut so, als ob er alles ___. (wissen)", options:["wüsste","weiß","wusste","gewusst"], answer:"wüsste", explain:"Nach 'als ob' (irreal) steht Konjunktiv II: *wüsste*."},
]);

add("passiv",
 "Passiv = *werden* + Partizip II. Präsens: wird gebaut. Präteritum: *wurde* gebaut. Perfekt: ist gebaut *worden* (nicht 'geworden'). Mit Modalverb: muss gemacht *werden*. Täter: *von* + Person, *durch* + Ursache/Mittel. Zustandspassiv (Zustand): *sein* + Partizip II ('ist geschlossen').",
[
 {lvl:"e", type:"mc", q:"Das neue Haus ___ gerade gebaut. (Präsens)", options:["wird","ist","hat","war"], answer:"wird", explain:"Präsens Passiv = *wird* + Partizip II."},
 {lvl:"e", type:"mc", q:"Der Brief ___ gestern geschrieben. (Präteritum)", options:["wurde","wird","ist","war"], answer:"wurde", explain:"Präteritum Passiv = *wurde* + Partizip II."},
 {lvl:"e", type:"fill", q:"Amerika wurde 1492 ___. (entdecken)", accept:["entdeckt"], explain:"entdecken → *entdeckt*."},
 {lvl:"e", type:"mc", q:"Hier ___ Deutsch gesprochen.", options:["wird","ist","hat","war"], answer:"wird", explain:"Präsens Passiv → *wird* gesprochen."},
 {lvl:"m", type:"transform", q:"Aktiv → Passiv (Präsens): „Man repariert das Auto.“", accept:["Das Auto wird repariert","wird repariert"], explain:"Objekt wird Subjekt: 'Das Auto *wird repariert*.'"},
 {lvl:"m", type:"mc", q:"Die Hausaufgaben müssen bis morgen ___ ___.", options:["gemacht werden","gemacht worden","machen werden","werden gemacht"], answer:"gemacht werden", explain:"Modalverb + Passiv = Partizip II + *werden*."},
 {lvl:"m", type:"mc", q:"Der Dieb ___ von der Polizei gefasst. (Präteritum)", options:["wurde","wird","ist","hat"], answer:"wurde", explain:"Präteritum Passiv → *wurde* gefasst."},
 {lvl:"m", type:"mc", q:"Der Kuchen wurde ___ meiner Oma gebacken.", options:["von","durch","mit","bei"], answer:"von", explain:"Der handelnde *Mensch* → *von*."},
 {lvl:"m", type:"mc", q:"In der Bibliothek ___ nicht laut gesprochen.", options:["wird","ist","hat","kann"], answer:"wird", explain:"Unpersönliches Passiv Präsens → *wird*."},
 {lvl:"m", type:"fill", q:"Das Formular muss zuerst unterschrieben ___. (werden)", accept:["werden"], explain:"Modalverb + Passiv: Partizip II + *werden*."},
 {lvl:"h", type:"mc", q:"Das Problem ist endlich gelöst ___. (Perfekt)", options:["worden","geworden","werden","wurde"], answer:"worden", explain:"Perfekt Passiv = ist + Partizip II + *worden* (nicht 'geworden')."},
 {lvl:"h", type:"transform", q:"Passiv Perfekt: „Man hat die Kirche 1850 gebaut.“ →", accept:["Die Kirche ist 1850 gebaut worden","ist 1850 gebaut worden"], explain:"'Die Kirche *ist* 1850 gebaut *worden*.'"},
 {lvl:"h", type:"mc", q:"Das Auto wurde ___ einen Unfall stark beschädigt.", options:["durch","von","mit","bei"], answer:"durch", explain:"Ursache/Mittel (kein Mensch) → *durch* + Akkusativ."},
 {lvl:"h", type:"mc", q:"Die Häuser ___ nach dem Krieg wieder aufgebaut. (Präteritum)", options:["wurden","wurde","sind","haben"], answer:"wurden", explain:"Passiv Präteritum, Plural → *wurden* aufgebaut."},
 {lvl:"h", type:"transform", q:"Aktiv → Passiv (Präteritum): „Der Lehrer lobte den Schüler.“", accept:["Der Schüler wurde gelobt","wurde gelobt","Der Schüler wurde vom Lehrer gelobt"], explain:"'Der Schüler *wurde* (vom Lehrer) *gelobt*.'"},
 {lvl:"h", type:"mc", q:"Das Geschäft ___ sonntags geschlossen. (Zustand)", options:["ist","wird","hat","worden"], answer:"ist", explain:"Zustandspassiv (Zustand, kein Vorgang) = *sein* + Partizip II: 'ist geschlossen'."},
]);

add("verbpraep",
 "Viele Verben haben eine *feste* Präposition – wie Vokabeln lernen! warten *auf*+A, denken *an*+A, sich freuen *auf*+A (Zukunft)/​*über*+A (jetzt), sich ärgern *über*+A, teilnehmen *an*+D, bestehen *aus*+D, abhängen *von*+D, sich bewerben *um*+A, sich bedanken *für*+A, fragen *nach*+D.",
[
 {lvl:"e", type:"mc", q:"Ich warte schon eine Stunde ___ den Bus.", options:["auf","an","für","über"], answer:"auf", explain:"warten *auf* + Akkusativ."},
 {lvl:"e", type:"mc", q:"Sie interessiert sich sehr ___ Kunst.", options:["für","an","auf","über"], answer:"für", explain:"sich interessieren *für* + Akkusativ."},
 {lvl:"e", type:"mc", q:"Ich denke oft ___ dich.", options:["an","auf","über","für"], answer:"an", explain:"denken *an* + Akkusativ."},
 {lvl:"e", type:"mc", q:"Wir freuen uns schon ___ die Ferien.", options:["auf","über","an","für"], answer:"auf", explain:"sich freuen *auf* + A (etwas Zukünftiges)."},
 {lvl:"e", type:"mc", q:"Er wartet ___ eine Antwort von dir.", options:["auf","an","für","über"], answer:"auf", explain:"warten *auf* + Akkusativ."},
 {lvl:"m", type:"mc", q:"Er ärgert sich ___ das schlechte Wetter.", options:["über","auf","an","für"], answer:"über", explain:"sich ärgern *über* + Akkusativ."},
 {lvl:"m", type:"fill", q:"Ich nehme morgen ___ dem Deutschkurs teil.", accept:["an"], explain:"teilnehmen *an* + Dativ."},
 {lvl:"m", type:"mc", q:"Ob wir grillen, hängt ___ dem Wetter ab.", options:["von","auf","an","über"], answer:"von", explain:"abhängen *von* + Dativ."},
 {lvl:"m", type:"mc", q:"Erinnerst du dich noch ___ unseren Lehrer?", options:["an","auf","über","von"], answer:"an", explain:"sich erinnern *an* + Akkusativ."},
 {lvl:"m", type:"fill", q:"Wasser besteht ___ Wasserstoff und Sauerstoff.", accept:["aus"], explain:"bestehen *aus* + Dativ."},
 {lvl:"m", type:"mc", q:"Ich muss mich noch ___ die Prüfung vorbereiten.", options:["auf","für","an","über"], answer:"auf", explain:"sich vorbereiten *auf* + Akkusativ."},
 {lvl:"m", type:"mc", q:"Die Mutter kümmert sich liebevoll ___ die Kinder.", options:["um","für","auf","an"], answer:"um", explain:"sich kümmern *um* + Akkusativ."},
 {lvl:"m", type:"mc", q:"Sie träumt ___ einer großen Weltreise.", options:["von","auf","an","über"], answer:"von", explain:"träumen *von* + Dativ."},
 {lvl:"h", type:"mc", q:"Ich freue mich sehr ___ dein schönes Geschenk!", options:["über","auf","an","für"], answer:"über", explain:"sich freuen *über* + A = sich über etwas Gegenwärtiges freuen."},
 {lvl:"h", type:"mc", q:"Wir haben lange ___ Politik diskutiert.", options:["über","auf","an","für"], answer:"über", explain:"diskutieren *über* + Akkusativ."},
 {lvl:"h", type:"mc", q:"Sie hat sich ___ die Stelle beworben.", options:["um","auf","für","an"], answer:"um", explain:"sich bewerben *um* + Akkusativ."},
 {lvl:"h", type:"mc", q:"Ich bedanke mich herzlich ___ deine Hilfe.", options:["für","über","auf","an"], answer:"für", explain:"sich bedanken *für* + Akkusativ."},
 {lvl:"h", type:"mc", q:"Er hat mich ___ meiner Meinung gefragt.", options:["nach","um","über","für"], answer:"nach", explain:"fragen *nach* + Dativ."},
 {lvl:"h", type:"mc", q:"Ich gewöhne mich langsam ___ das kalte Klima.", options:["an","auf","über","für"], answer:"an", explain:"sich gewöhnen *an* + Akkusativ."},
 {lvl:"h", type:"fill", q:"Bitte pass gut ___ die Kinder auf. (aufpassen …)", accept:["auf"], explain:"aufpassen *auf* + Akkusativ."},
]);

add("reflexiv",
 "Reflexivpronomen im *Akkusativ*: mich, dich, *sich*, uns, euch, sich. Gibt es zusätzlich ein Akkusativobjekt, steht es im *Dativ* (mir, dir): 'Ich wasche *mir* die Hände.' Immer Dativ: sich etwas *merken/vorstellen/wünschen/leisten*.",
[
 {lvl:"e", type:"mc", q:"Ich freue ___ auf das Wochenende.", options:["mich","mir","sich","mein"], answer:"mich", explain:"sich freuen (Akkusativ) → ich freue *mich*."},
 {lvl:"e", type:"mc", q:"Wir müssen ___ beeilen, der Zug fährt gleich!", options:["uns","sich","euch","mich"], answer:"uns", explain:"1. Person Plural → *uns*."},
 {lvl:"e", type:"mc", q:"Setz ___ bitte auf diesen Stuhl! (du)", options:["dich","dir","sich","du"], answer:"dich", explain:"sich setzen (Akkusativ) → setz *dich*."},
 {lvl:"e", type:"mc", q:"Sie zieht ___ schnell an.", options:["sich","ihr","sie","mich"], answer:"sich", explain:"3. Person → *sich* (sich anziehen)."},
 {lvl:"e", type:"mc", q:"Wie fühlst du ___ heute?", options:["dich","dir","sich","du"], answer:"dich", explain:"sich fühlen (Akkusativ) → du fühlst *dich*."},
 {lvl:"m", type:"mc", q:"Ich putze ___ die Zähne. (Objekt: die Zähne)", options:["mir","mich","mein","sich"], answer:"mir", explain:"Akkusativobjekt 'die Zähne' → Reflexivpronomen im *Dativ*: *mir*."},
 {lvl:"m", type:"mc", q:"Wäschst du ___ vor dem Essen die Hände?", options:["dir","dich","du","sich"], answer:"dir", explain:"Akkusativobjekt 'die Hände' → Dativ *dir*."},
 {lvl:"m", type:"mc", q:"Im Urlaub erholen sie ___ richtig gut.", options:["sich","ihnen","ihr","uns"], answer:"sich", explain:"3. Person Plural, sich erholen → *sich*."},
 {lvl:"m", type:"mc", q:"Habt ihr ___ schon kennengelernt?", options:["euch","sich","uns","ihr"], answer:"euch", explain:"2. Person Plural → *euch*."},
 {lvl:"m", type:"mc", q:"Kannst du ___ das leisten? (sich etwas leisten)", options:["dir","dich","du","sich"], answer:"dir", explain:"'sich etwas leisten' verlangt immer *Dativ*: *dir*."},
 {lvl:"h", type:"mc", q:"Ich habe ___ den Termin gut gemerkt. (sich etwas merken)", options:["mir","mich","mein","sich"], answer:"mir", explain:"'sich etwas merken' → *Dativ*: *mir*."},
 {lvl:"h", type:"mc", q:"Kannst du ___ das überhaupt vorstellen? (sich etwas vorstellen)", options:["dir","dich","du","sich"], answer:"dir", explain:"'sich etwas vorstellen' (imaginieren) → *Dativ*: *dir*."},
 {lvl:"h", type:"mc", q:"Ich wünsche ___ zum Geburtstag ein Fahrrad. (sich etwas wünschen)", options:["mir","mich","mein","sich"], answer:"mir", explain:"'sich etwas wünschen' → *Dativ*: *mir*."},
 {lvl:"h", type:"mc", q:"Er hat ___ beim Sport verletzt.", options:["sich","ihm","ihn","mir"], answer:"sich", explain:"sich verletzen (Akkusativ), 3. Person → *sich*."},
 {lvl:"h", type:"mc", q:"Wir treffen ___ heute Abend um acht.", options:["uns","sich","euch","mich"], answer:"uns", explain:"sich treffen, 1. Person Plural → *uns*."},
 {lvl:"h", type:"mc", q:"Beeil ___, wir sind schon spät dran! (du)", options:["dich","dir","sich","du"], answer:"dich", explain:"sich beeilen (Akkusativ), Imperativ du → *dich*."},
]);

add("infinitiv",
 "Viele Ausdrücke brauchen *zu* + Infinitiv (Ich hoffe, dich *zu* sehen). Trennbare Verben: zu *in der Mitte* (an*zu*rufen). *um … zu* = Absicht (gleiches Subjekt); verschiedene Subjekte → *damit*. *ohne … zu* = ohne dass. *(an)statt … zu* = anstatt dass. Nach Modalverben & werden: *kein* zu!",
[
 {lvl:"e", type:"mc", q:"Ich habe vergessen, die Tür ___. (abschließen)", options:["abzuschließen","zu abschließen","abschließen","abgeschlossen"], answer:"abzuschließen", explain:"Trennbar → zu in der Mitte: ab*zu*schließen."},
 {lvl:"e", type:"fill", q:"Es ist wichtig, jeden Tag ___ ___. (üben)", accept:["zu üben"], explain:"'Es ist wichtig, …' + *zu* + Infinitiv: 'zu üben'."},
 {lvl:"e", type:"mc", q:"Ich möchte heute früh nach Hause ___.", options:["gehen","zu gehen","gegangen","zu geht"], answer:"gehen", explain:"Nach dem Modalverb (möchte) steht der Infinitiv *ohne* zu."},
 {lvl:"e", type:"mc", q:"Er geht zur Uni, ___ Deutsch ___ studieren.", options:["um … zu","damit … zu","ohne … zu","statt … zu"], answer:"um … zu", explain:"Absicht bei gleichem Subjekt → *um … zu*."},
 {lvl:"e", type:"fill", q:"Ich freue mich, dich bald ___ ___. (sehen)", accept:["zu sehen"], explain:"Nach 'sich freuen' folgt *zu* + Infinitiv: 'zu sehen'."},
 {lvl:"m", type:"mc", q:"Ich lerne jeden Tag, ___ die Prüfung zu bestehen.", options:["um","damit","ohne","statt"], answer:"um", explain:"Ziel, gleiches Subjekt → *um* … zu."},
 {lvl:"m", type:"mc", q:"Sie ging weg, ___ sich zu verabschieden.", options:["ohne","um","statt","damit"], answer:"ohne", explain:"'ohne sich zu verabschieden' → *ohne … zu*."},
 {lvl:"m", type:"mc", q:"Vergiss bitte nicht, mich später ___! (anrufen)", options:["anzurufen","zu anrufen","anrufen","angerufen"], answer:"anzurufen", explain:"Trennbar: an*zu*rufen."},
 {lvl:"m", type:"mc", q:"___ zu arbeiten, spielte er den ganzen Tag.", options:["Statt","Um","Ohne","Damit"], answer:"Statt", explain:"'(an)statt zu arbeiten' → *statt … zu*."},
 {lvl:"m", type:"mc", q:"Ich erkläre es dir noch einmal, ___ du es verstehst.", options:["damit","um … zu","ohne","statt"], answer:"damit", explain:"Verschiedene Subjekte (ich / du) → *damit*."},
 {lvl:"m", type:"fill", q:"Hast du Lust, mit mir ins Kino ___ ___? (gehen)", accept:["zu gehen"], explain:"'Lust haben, …' + *zu* + Infinitiv: 'zu gehen'."},
 {lvl:"h", type:"fill", q:"Er hat endlich aufgehört ___ ___. (rauchen)", accept:["zu rauchen"], explain:"'aufhören' + *zu* + Infinitiv: 'zu rauchen'."},
 {lvl:"h", type:"fill", q:"Ich hoffe, dich bald wieder ___ ___. (treffen)", accept:["zu treffen"], explain:"'hoffen' + *zu* + Infinitiv: 'zu treffen'."},
 {lvl:"h", type:"fill", q:"Es ist streng verboten, hier ___ ___. (parken)", accept:["zu parken"], explain:"'Es ist verboten, …' + *zu* + Infinitiv: 'zu parken'."},
 {lvl:"h", type:"fill", q:"Sie verließ das Haus, ohne die Tür ___ ___. (abschließen)", accept:["abzuschließen"], explain:"ohne … zu, trennbar → 'ab*zu*schließen'."},
 {lvl:"h", type:"mc", q:"Er ist alt genug, ___ allein ___ reisen.", options:["um … zu","damit","ohne","statt"], answer:"um … zu", explain:"'alt genug, *um* … *zu* reisen' – Absicht/Folge, gleiches Subjekt."},
 {lvl:"h", type:"mc", q:"Welcher Satz ist korrekt?", options:["Ich versuche, früher aufzustehen.","Ich versuche, früher aufstehen zu."], answer:"Ich versuche, früher aufzustehen.", explain:"Trennbar → 'auf*zu*stehen' (zu in der Mitte, Infinitiv am Ende)."},
]);

add("modal",
 "Modalverben: *können* (Fähigkeit/Möglichkeit), *müssen* (Notwendigkeit), *dürfen* (Erlaubnis), *sollen* (Auftrag/Rat), *wollen* (Wille), *möchten* (höflich). Position 2, Infinitiv am Ende. Präteritum ohne Umlaut: konnte, musste, durfte. Vermutung: *muss* (sicher), *könnte* (vielleicht).",
[
 {lvl:"e", type:"mc", q:"Hier ___ du nicht rauchen, das ist verboten.", options:["darfst","musst","willst","kannst"], answer:"darfst", explain:"Verbot = keine Erlaubnis → nicht *dürfen*."},
 {lvl:"e", type:"mc", q:"Ich ___ heute arbeiten, ich habe keine Wahl.", options:["muss","darf","will","möchte"], answer:"muss", explain:"Notwendigkeit → *müssen*."},
 {lvl:"e", type:"mc", q:"___ du schwimmen?", options:["Kannst","Musst","Darfst","Sollst"], answer:"Kannst", explain:"Fähigkeit → *können*."},
 {lvl:"e", type:"mc", q:"Ich ___ bitte ein Wasser. (höflicher Wunsch)", options:["möchte","muss","darf","soll"], answer:"möchte", explain:"Höflicher Wunsch → *möchte*."},
 {lvl:"e", type:"mc", q:"In der Bibliothek ___ man leise sein.", options:["muss","will","möchte","mag"], answer:"muss", explain:"Regel / Notwendigkeit → *müssen*."},
 {lvl:"m", type:"fill", q:"Präteritum von *müssen* (ich)?", accept:["musste"], explain:"müssen → *musste* (kein Umlaut)."},
 {lvl:"m", type:"mc", q:"Als Kind ___ ich abends nicht lange fernsehen.", options:["durfte","konnte","musste","wollte"], answer:"durfte", explain:"'nicht dürfen' = keine Erlaubnis; Präteritum → *durfte*."},
 {lvl:"m", type:"mc", q:"Was ___ das denn bedeuten?", options:["soll","will","mag","darf"], answer:"soll", explain:"Feste Wendung 'Was *soll* das bedeuten?'"},
 {lvl:"m", type:"mc", q:"Welcher Satz ist korrekt?", options:["Ich kann heute nicht kommen.","Ich kann heute nicht zu kommen."], answer:"Ich kann heute nicht kommen.", explain:"Modalverb + Infinitiv *ohne* zu; Infinitiv am Ende."},
 {lvl:"m", type:"fill", q:"Präteritum von *können* (ich)?", accept:["konnte"], explain:"können → *konnte*."},
 {lvl:"m", type:"mc", q:"Du ___ nicht so laut sein, die Kinder schlafen.", options:["sollst","darfst","kannst","willst"], answer:"sollst", explain:"Aufforderung / Auftrag → *sollen*."},
 {lvl:"h", type:"mc", q:"Er sagt, dass er heute nicht kommen ___.", options:["kann","können","kannst","gekonnt"], answer:"kann", explain:"Im Nebensatz steht das Modalverb ganz am Ende (nach dem Infinitiv): '…kommen *kann*'."},
 {lvl:"h", type:"mc", q:"Das ___ wahr sein – ich habe es selbst gesehen!", options:["muss","darf","soll","mag"], answer:"muss", explain:"Sichere Vermutung → *müssen*: 'Das muss (sicher) wahr sein.'"},
 {lvl:"h", type:"mc", q:"Er ___ krank sein, er sieht sehr blass aus.", options:["könnte","muss","darf","will"], answer:"könnte", explain:"Vorsichtige Vermutung (vielleicht) → *könnte*."},
 {lvl:"h", type:"fill", q:"Präteritum von *dürfen* (ich)?", accept:["durfte"], explain:"dürfen → *durfte* (kein Umlaut)."},
 {lvl:"h", type:"mc", q:"Ich habe die ganze Nacht arbeiten ___. (Perfekt)", options:["müssen","gemusst","musste","gemüsst"], answer:"müssen", explain:"Perfekt mit Modalverb + Vollverb = doppelter Infinitiv: 'habe arbeiten *müssen*'."},
 {lvl:"h", type:"mc", q:"Man ___ Rücksicht auf andere nehmen. (Rat)", options:["sollte","darf","mag","will"], answer:"sollte", explain:"Genereller Rat → *sollte* (Konjunktiv von sollen)."},
]);

add("ndekl",
 "n-Deklination: bestimmte *maskuline* Nomen bekommen in allen Fällen außer Nominativ Singular ein *-(e)n*. Typisch: der Junge, Kollege, Kunde, Nachbar, Mensch, Student, Polizist, Journalist, Präsident; der Herr (den *Herrn* Sg., die *Herren* Pl.); der Name (Genitiv: des *Namens*).",
[
 {lvl:"e", type:"mc", q:"Ich kenne den ___ dort drüben. (der Junge)", options:["Jungen","Junge","Junges","Jungn"], answer:"Jungen", explain:"Akkusativ → den *Jungen*."},
 {lvl:"e", type:"mc", q:"Ich helfe dem ___ bei den Aufgaben. (der Student)", options:["Studenten","Student","Studentem","Studentes"], answer:"Studenten", explain:"Dativ → dem *Studenten*."},
 {lvl:"e", type:"mc", q:"Viele ___ studieren an dieser Uni. (Plural)", options:["Studenten","Student","Studente","Studentes"], answer:"Studenten", explain:"Plural → die *Studenten*."},
 {lvl:"e", type:"mc", q:"Kennst du diesen ___? (der Mensch)", options:["Menschen","Mensch","Menschem","Mensches"], answer:"Menschen", explain:"Akkusativ → diesen *Menschen*."},
 {lvl:"m", type:"mc", q:"Ich spreche gerade mit meinem ___. (der Nachbar)", options:["Nachbarn","Nachbar","Nachbarem","Nachbars"], answer:"Nachbarn", explain:"Dativ → mit meinem *Nachbarn*."},
 {lvl:"m", type:"mc", q:"Das ist die Tasche des ___. (der Herr)", options:["Herrn","Herr","Herren","Herrs"], answer:"Herrn", explain:"Genitiv Singular → des *Herrn*."},
 {lvl:"m", type:"mc", q:"Der Chef hat einen neuen ___ eingestellt. (der Kollege)", options:["Kollegen","Kollege","Kolleg","Kolleges"], answer:"Kollegen", explain:"Akkusativ → einen *Kollegen*."},
 {lvl:"m", type:"mc", q:"Ich gebe dem ___ die Rechnung. (der Kunde)", options:["Kunden","Kunde","Kundem","Kundes"], answer:"Kunden", explain:"Dativ → dem *Kunden*."},
 {lvl:"m", type:"mc", q:"Wir haben einen neuen ___ gewählt. (der Präsident)", options:["Präsidenten","Präsident","Präsidentem","Präsidents"], answer:"Präsidenten", explain:"Akkusativ → einen *Präsidenten*."},
 {lvl:"h", type:"mc", q:"Der Name des ___ ist mir entfallen. (der Junge, Genitiv)", options:["Jungen","Junges","Jungs","Junge"], answer:"Jungen", explain:"Genitiv der n-Deklination → des *Jungen*."},
 {lvl:"h", type:"mc", q:"Ich habe mit einem ___ gesprochen. (der Journalist)", options:["Journalisten","Journalist","Journalistem","Journalists"], answer:"Journalisten", explain:"Dativ → mit einem *Journalisten*."},
 {lvl:"h", type:"mc", q:"___ heißt Max. (der Name — Nominativ Singular!)", options:["Der Name","Den Namen","Dem Namen","Des Namens"], answer:"Der Name", explain:"Nominativ Singular ist die *einzige* Form ohne -n: der *Name*."},
 {lvl:"h", type:"mc", q:"Der Genitiv von „der Name“ lautet: des ___.", options:["Namens","Namen","Name","Namn"], answer:"Namens", explain:"Sonderform: des *Namens* (mit -ns)."},
 {lvl:"h", type:"mc", q:"Sie sprach mit vielen ___. (der Experte, Dativ Plural)", options:["Experten","Experte","Expertn","Expertes"], answer:"Experten", explain:"Dativ Plural → mit vielen *Experten*."},
]);

add("wortstellung",
 "Mittelfeld *TeKaMoLo*: *Te*mporal (wann) – *Ka*usal (warum) – *Mo*dal (wie) – *Lo*kal (wohin/wo). Hauptsatz: Verb an Position 2 (bei Inversion Subjekt danach). Zwei Objekte: Dativ vor Akkusativ (Nomen); Pronomen zuerst, Akkusativpronomen vor Dativ. *nicht* meist vor dem, was verneint wird.",
[
 {lvl:"e", type:"mc", q:"Morgen ___ ich nach Hamburg.", options:["fahre","fahren","gefahren","fährst"], answer:"fahre", explain:"Steht ein Wort vorn, kommt das Verb auf Position 2: 'Morgen *fahre* ich …'"},
 {lvl:"e", type:"mc", q:"Welcher Satz ist korrekt?", options:["Gestern hat er einen Kuchen gebacken.","Gestern er hat einen Kuchen gebacken."], answer:"Gestern hat er einen Kuchen gebacken.", explain:"Nach vorangestelltem Wort folgt Inversion: Verb vor Subjekt ('hat er')."},
 {lvl:"e", type:"mc", q:"Ich weiß, dass er heute ___.", options:["kommt","zu kommen","kommen","kommt nicht heute"], answer:"kommt", explain:"Im Nebensatz mit *dass* steht das Verb am Ende."},
 {lvl:"e", type:"mc", q:"Ich kenne ihn ___.", options:["nicht","kein","nichts","nein"], answer:"nicht", explain:"*nicht* verneint das Verb/den Satz."},
 {lvl:"m", type:"mc", q:"Welcher Satz ist korrekt?", options:["Ich fahre morgen mit dem Auto nach Berlin.","Ich fahre mit dem Auto morgen nach Berlin."], answer:"Ich fahre morgen mit dem Auto nach Berlin.", explain:"TeKaMoLo: temporal (morgen) vor modal (mit dem Auto) vor lokal (nach Berlin)."},
 {lvl:"m", type:"mc", q:"Wir treffen uns ___.", options:["am Freitag im Café","im Café am Freitag"], answer:"am Freitag im Café", explain:"Temporal (am Freitag) vor Lokal (im Café)."},
 {lvl:"m", type:"mc", q:"Ich gebe ___. (zwei Nomen)", options:["dem Kind das Buch","das Buch dem Kind"], answer:"dem Kind das Buch", explain:"Bei zwei Nomen: *Dativ vor Akkusativ*."},
 {lvl:"m", type:"mc", q:"Ich gebe ___. (zwei Pronomen)", options:["es dir","dir es"], answer:"es dir", explain:"Bei Pronomen steht Akkusativ *vor* Dativ → 'es dir'."},
 {lvl:"m", type:"mc", q:"Ich habe heute leider ___ Zeit.", options:["keine","nicht","nichts","kein"], answer:"keine", explain:"Nomen (Zeit, f) verneint man mit *kein-*: *keine* Zeit."},
 {lvl:"h", type:"mc", q:"Ich schenke ___. (Pronomen + Nomen)", options:["ihr einen Ring","einen Ring ihr"], answer:"ihr einen Ring", explain:"Dativ-*Pronomen* steht vor dem Akkusativ-Nomen → 'ihr einen Ring'."},
 {lvl:"h", type:"mc", q:"Welcher Satz ist korrekt (Stellung von 'nicht')?", options:["Ich habe das Buch nicht gelesen.","Ich habe nicht das Buch gelesen."], answer:"Ich habe das Buch nicht gelesen.", explain:"Satznegation: *nicht* steht vor dem Partizip/am Ende des Mittelfelds."},
 {lvl:"h", type:"mc", q:"Der Film war ___ gut.", options:["nicht","kein","nichts","nein"], answer:"nicht", explain:"Vor einem Adjektiv verneint *nicht*: 'nicht gut'."},
 {lvl:"h", type:"mc", q:"Deshalb ___ wir heute zu Hause.", options:["bleiben","wir bleiben","geblieben","zu bleiben"], answer:"bleiben", explain:"Nach *deshalb* (Position 1) steht das Verb auf Position 2: 'bleiben wir'."},
 {lvl:"h", type:"mc", q:"Kannst du mir sagen, wann der Film ___?", options:["beginnt","beginnen","zu beginnen","begonnen"], answer:"beginnt", explain:"Indirekte Frage = Nebensatz → Verb am Ende: '…wann der Film *beginnt*'."},
]);

add("indirekt",
 "Indirekte Fragen sind Nebensätze → Verb am *Ende*. Ja/Nein-Frage → *ob*. W-Frage → Fragewort (wann, wo, wie, warum, wer, was, welche…). 'Weißt du, *wo* er *wohnt*?' Trennbare Verben stehen am Ende zusammen ('…warum er nicht *anruft*').",
[
 {lvl:"e", type:"mc", q:"Weißt du, ___ er heute noch kommt?", options:["ob","dass","wenn","was"], answer:"ob", explain:"Ja/Nein-Frage indirekt → *ob*."},
 {lvl:"e", type:"mc", q:"Sag mir bitte, ___ du wohnst.", options:["wo","ob","dass","wenn"], answer:"wo", explain:"Frage nach dem Ort → *wo*."},
 {lvl:"e", type:"mc", q:"Ich weiß noch nicht, ___ ich das schaffe.", options:["ob","dass","wenn","was"], answer:"ob", explain:"Unsicherheit / Ja-Nein → *ob*."},
 {lvl:"e", type:"mc", q:"Sie hat gefragt, ___ ich Zeit habe.", options:["ob","dass","wenn","wann"], answer:"ob", explain:"Ja/Nein-Frage indirekt → *ob* (nicht 'wenn')."},
 {lvl:"m", type:"mc", q:"Ich frage mich, ___ das Ticket kostet.", options:["wie viel","ob","dass","wenn"], answer:"wie viel", explain:"Frage nach dem Preis → *wie viel*."},
 {lvl:"m", type:"mc", q:"Können Sie mir sagen, wo der Bahnhof ___?", options:["ist","zu sein","sein","ist hier nicht"], answer:"ist", explain:"Indirekter Fragesatz → Verb am Ende: '…wo der Bahnhof *ist*.'"},
 {lvl:"m", type:"mc", q:"Weißt du, ___ der Zug abfährt? (Uhrzeit)", options:["wann","wenn","als","ob"], answer:"wann", explain:"Frage nach der Zeit → *wann*."},
 {lvl:"m", type:"mc", q:"Ich möchte wissen, ___ ich mich anmelden kann.", options:["wie","ob","dass","wenn"], answer:"wie", explain:"Frage nach der Art und Weise → *wie*."},
 {lvl:"h", type:"mc", q:"Sie fragt, ___ ich Hunger habe.", options:["ob","dass","wenn","wie"], answer:"ob", explain:"Ja/Nein-Frage indirekt → *ob*; Verb 'habe' am Ende."},
 {lvl:"h", type:"mc", q:"Ich weiß nicht, ___ ich zuerst machen soll.", options:["was","ob","dass","wenn"], answer:"was", explain:"Frage nach der Sache → Fragewort *was*."},
 {lvl:"h", type:"mc", q:"Können Sie mir sagen, ___ ich zum Zentrum komme?", options:["wie","ob","dass","wann"], answer:"wie", explain:"Nach dem Weg fragen → *wie* (komme ich …)."},
 {lvl:"h", type:"mc", q:"Weißt du, ___ Frau das ist?", options:["welche","wer","was","wie"], answer:"welche", explain:"Vor einem Nomen (Frau) → Fragewort *welche*."},
 {lvl:"h", type:"mc", q:"Ich frage mich, warum er nicht ___.", options:["anruft","ruft an","anrufen","angerufen"], answer:"anruft", explain:"Im Nebensatz steht das trennbare Verb am Ende zusammen: *anruft*."},
]);

add("futur",
 "Futur I = *werden* (konjugiert) + Infinitiv am Satzende. Für die Zukunft (oft mit Zeitangabe) und für Vermutungen (mit *wohl*). werden: ich *werde*, du *wirst*, er *wird*, wir/sie *werden*, ihr *werdet*. Im Nebensatz steht *werden* ganz am Ende.",
[
 {lvl:"e", type:"mc", q:"Ich ___ morgen einen Kuchen backen.", options:["werde","wird","werden","wirst"], answer:"werde", explain:"ich → *werde* + Infinitiv (backen)."},
 {lvl:"e", type:"mc", q:"Du ___ das bestimmt schaffen!", options:["wirst","werde","wird","werdet"], answer:"wirst", explain:"du → *wirst*."},
 {lvl:"e", type:"mc", q:"Er ___ bald ankommen.", options:["wird","werde","wirst","werden"], answer:"wird", explain:"er → *wird*."},
 {lvl:"e", type:"mc", q:"Wir ___ im Sommer nach Italien fahren.", options:["werden","werde","wird","wirst"], answer:"werden", explain:"wir → *werden*."},
 {lvl:"m", type:"fill", q:"Konjugiere *werden* für *ihr*: Ihr ___ es schon lernen.", accept:["werdet"], explain:"ihr → *werdet*."},
 {lvl:"m", type:"mc", q:"Sie (Plural) ___ uns nächste Woche besuchen.", options:["werden","wird","werdet","werde"], answer:"werden", explain:"sie (Plural) → *werden*."},
 {lvl:"m", type:"transform", q:"Setze ins Futur I: „Ich lerne Deutsch.“", accept:["Ich werde Deutsch lernen","werde Deutsch lernen"], explain:"werden + Infinitiv am Ende: 'Ich *werde* Deutsch *lernen*.'"},
 {lvl:"m", type:"mc", q:"Er ist nicht da. Er ___ wohl krank sein. (Vermutung)", options:["wird","werde","ist","war"], answer:"wird", explain:"Futur I mit *wohl* drückt eine Vermutung aus → *wird*."},
 {lvl:"m", type:"mc", q:"Laut Wetterbericht ___ es morgen regnen.", options:["wird","werde","wirst","ist"], answer:"wird", explain:"Zukunft (es) → *wird* … regnen."},
 {lvl:"h", type:"transform", q:"Setze ins Futur I: „Wir kaufen ein Haus.“", accept:["Wir werden ein Haus kaufen","werden ein Haus kaufen"], explain:"'Wir *werden* ein Haus *kaufen*.'"},
 {lvl:"h", type:"mc", q:"Welcher Satz ist korrekt?", options:["Ich werde dich morgen anrufen.","Ich werde anrufen dich morgen."], answer:"Ich werde dich morgen anrufen.", explain:"Der Infinitiv steht am Ende: '…morgen *anrufen*.'"},
 {lvl:"h", type:"mc", q:"Ich glaube, dass er morgen kommen ___.", options:["wird","werden","wirst","werde"], answer:"wird", explain:"Im Nebensatz steht *werden* ganz am Ende (nach dem Infinitiv): '…kommen *wird*'."},
 {lvl:"h", type:"mc", q:"„Wo ist Anna?“ – „Sie ___ wohl noch im Büro sein.“", options:["wird","werden","ist","war"], answer:"wird", explain:"Vermutung über die Gegenwart mit *wird … wohl*."},
 {lvl:"h", type:"transform", q:"Setze ins Futur I: „Ich rufe dich an.“", accept:["Ich werde dich anrufen","werde dich anrufen"], explain:"'Ich *werde* dich *anrufen*.'"},
]);

add("wortschatz",
 "Feste Nomen-Verb-Verbindungen für B1: eine Entscheidung *treffen*, eine Frage *stellen*, einen Fehler *machen*, Spaß *machen*, Angst *haben*, recht *haben*, eine Rolle *spielen*, Bescheid *sagen*, ein Versprechen *halten*, eine Prüfung *bestehen*, Wert *legen* auf, in Frage *kommen* – am besten als ganze Wendung lernen.",
[
 {lvl:"e", type:"mc", q:"Ich muss eine wichtige Entscheidung ___.", options:["treffen","machen","nehmen","geben"], answer:"treffen", explain:"eine Entscheidung *treffen*."},
 {lvl:"e", type:"mc", q:"Darf ich dir eine Frage ___?", options:["stellen","machen","fragen","geben"], answer:"stellen", explain:"eine Frage *stellen*."},
 {lvl:"e", type:"mc", q:"Das Spiel macht mir großen ___.", options:["Spaß","Angst","Recht","Rolle"], answer:"Spaß", explain:"(jemandem) Spaß *machen*."},
 {lvl:"e", type:"mc", q:"Keine Sorge – jeder macht mal einen ___.", options:["Fehler","Frage","Angst","Rolle"], answer:"Fehler", explain:"einen Fehler *machen*."},
 {lvl:"m", type:"mc", q:"Du hast völlig ___. Ich stimme dir zu.", options:["recht","Angst","Glück","Spaß"], answer:"recht", explain:"recht *haben* = richtig liegen."},
 {lvl:"m", type:"mc", q:"Ich habe ___ vor großen Hunden.", options:["Angst","Spaß","recht","Rolle"], answer:"Angst", explain:"Angst *haben* (vor + Dativ)."},
 {lvl:"m", type:"mc", q:"Gesundheit spielt eine große ___ in meinem Leben.", options:["Rolle","Spaß","Angst","Frage"], answer:"Rolle", explain:"eine Rolle *spielen* = wichtig sein."},
 {lvl:"m", type:"mc", q:"Sag mir bitte ___, wenn du ankommst.", options:["Bescheid","Angst","Rolle","Frage"], answer:"Bescheid", explain:"(jemandem) Bescheid *sagen* = informieren."},
 {lvl:"m", type:"mc", q:"Kannst du mir einen ___ tun?", options:["Gefallen","Dienst","Hilfe","Bitte"], answer:"Gefallen", explain:"(jemandem) einen Gefallen *tun*."},
 {lvl:"h", type:"mc", q:"Mach dir keine ___, es wird schon klappen.", options:["Sorgen","Angst","Fehler","Rolle"], answer:"Sorgen", explain:"sich Sorgen *machen* → 'Mach dir keine Sorgen'."},
 {lvl:"h", type:"mc", q:"Er hat sein Versprechen ___.", options:["gehalten","gemacht","genommen","gegeben"], answer:"gehalten", explain:"ein Versprechen *halten* (Partizip: gehalten)."},
 {lvl:"h", type:"mc", q:"Sie hat die Prüfung mit Bestnote ___.", options:["bestanden","gefallen","genommen","getroffen"], answer:"bestanden", explain:"eine Prüfung *bestehen* (Partizip: bestanden)."},
 {lvl:"h", type:"mc", q:"Ein Umzug? Das kommt für mich nicht in ___!", options:["Frage","Rede","Ordnung","Zweifel"], answer:"Frage", explain:"in Frage *kommen* = möglich sein; verneint = ausgeschlossen."},
 {lvl:"h", type:"mc", q:"Ich lege großen ___ auf Pünktlichkeit.", options:["Wert","Preis","Sinn","Grund"], answer:"Wert", explain:"Wert *legen* auf + A = etwas wichtig finden."},
 {lvl:"h", type:"mc", q:"Er hat mir einen guten ___ gegeben.", options:["Rat","Fehler","Frage","Rolle"], answer:"Rat", explain:"(jemandem) einen Rat *geben* = einen Tipp geben."},
]);
